<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $order_id
 * @property string $author_id
 * @property string $subject_id
 * @property string|null $listing_id
 * @property string $role
 * @property int $rating
 * @property string|null $comment
 * @property array|null $tags
 * @property bool $is_hidden
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Review extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'rv';

    protected $fillable = ['order_id', 'author_id', 'subject_id', 'listing_id', 'role', 'rating', 'comment', 'tags', 'is_hidden'];

    protected function casts(): array
    {
        return [
            'tags' => 'array',
            'rating' => 'integer',
            'is_hidden' => 'boolean',
        ];
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }

    /** @return BelongsTo<User, $this> */
    public function author(): BelongsTo
    {
        return $this->belongsTo(User::class, 'author_id');
    }

    /** @return BelongsTo<User, $this> */
    public function subject(): BelongsTo
    {
        return $this->belongsTo(User::class, 'subject_id');
    }
}
